present quiz "my-quiz" {
  rules {
    rule start "intro" {
      slide {
        content text {
          "# Quiz Presentation"
          "## Let's get started!"
        }
      }
    }
    rule content "questions" {
      slide {
        content text {
          "# Question"
          "This is a sample question slide"
        }
      }
    }
    rule end "thanks" {
      slide {
        content text {
          "# Thank You!"
        }
      }
    }
  }
}

